let lang='zh', selected=[72,48,24,12];
const $=id=>document.getElementById(id), t=key=>copy[lang][key];
function render(){for(const [id,key] of [['low','low'],['recovery','recovery'],['expiry','expiry'],['auto','auto']])$(id).setAttribute('aria-label',t(key));document.querySelectorAll('.close').forEach(b=>b.setAttribute('aria-label',t('close')));document.documentElement.lang=lang==='zh'?'zh-CN':'en'; document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));$('language').textContent=lang==='zh'?'EN':'中文'; const scenario=$('scenario').value||'collect';$('scenario').replaceChildren(...Object.entries(t('scenarios')).map(([value,item])=>{const o=new Option(item[0],value);return o}));$('scenario').value=scenario;updateNodes();renderStatus();}
function message(id,key,error=false){$(id).textContent=t(key);$(id).classList.toggle('error',error)}
function updateNodes(){const enabled=$('expiry').checked;$('nodes').disabled=!enabled;document.querySelectorAll('#nodes input').forEach(i=>{i.checked=selected.includes(+i.value);i.disabled=enabled&&selected.length===1&&i.checked});$('rule').textContent=enabled?t('rule').replace('{nodes}',selected.join(' / '))+(selected.length===1?' '+t('last'):''):t('ruleOff');}
function openDialog(id){if(!$(id).open)$(id).showModal();$('status').classList.toggle('active',id==='data-dialog');$('reminders').classList.toggle('active',id!=='data-dialog');}
function renderStatus(){const state=$('scenario').value||'collect',s=t('scenarios')[state];const blocked=['auth','stale'].includes(state);const root=$('status-content');root.replaceChildren();const heading=document.createElement('div');heading.className='state-head';const dot=document.createElement('span');dot.className='dot'+(blocked?' warn':'');const title=document.createElement('h2');title.textContent=s[1];heading.append(dot,title);const description=document.createElement('p');description.className='muted';description.textContent=s[2];const dl=document.createElement('dl');[[t('source'),state==='auth'?t('none'):t('sourceValue')],[t('successAt'),state==='auth'?t('none'):state==='stale'?'09:32':'09:41'],[t('attemptAt'),'09:41']].forEach(([k,v])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;dl.append(dt,dd)});const pace=document.createElement('div');pace.className='pace';const h=document.createElement('h2');h.textContent=t('observation');const value=document.createElement('p');value.textContent=s[3];pace.append(h,value);if(['collect','gap'].includes(state)){const meter=document.createElement('div');meter.className='meter';meter.setAttribute('aria-hidden','true');const bar=document.createElement('span');bar.style.width=state==='collect'?'60%':'27%';meter.append(bar);pace.append(meter)}const reason=document.createElement('p');reason.className='muted';reason.textContent=s[4];const limit=document.createElement('p');limit.className='muted';limit.textContent=t('limited');pace.append(reason,limit);root.append(heading,description,dl,pace);$('retry').textContent=t(state==='auth'?'retryCredentials':'refresh');$('retry-result').textContent='';}
$('language').onclick=()=>{lang=lang==='zh'?'en':'zh';document.querySelectorAll('.feedback').forEach(e=>e.textContent='');render()};$('expiry').onchange=()=>{updateNodes();message('save-status','saved')};document.querySelectorAll('#nodes input').forEach(i=>i.onchange=()=>{if($('failure').checked){$('failure').checked=false;message('save-status','failed',true)}else{selected=[...document.querySelectorAll('#nodes input:checked')].map(i=>+i.value);message('save-status','saved')}updateNodes()});$('auto').onchange=()=>{if($('auto').checked){$('auto').checked=false;openDialog('auto-dialog')}};$('confirm-auto').onclick=()=>{$('auto').checked=true;$('auto-dialog').close()};$('data-button').onclick=$('status').onclick=()=>openDialog('data-dialog');$('reminders').onclick=()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('reminders').classList.add('active')};$('scenario').onchange=renderStatus;$('retry').onclick=()=>message('retry-result',$('scenario').value==='auth'?'credentialResult':'refreshResult');$('system').onclick=()=>message('delivery-result','systemResult');$('test').onclick=()=>message('delivery-result','testResult');$('history').onclick=()=>openDialog('history-dialog');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{$('status').classList.remove('active');$('reminders').classList.add('active')}));$('reminders').classList.add('active');render();
